#include <string>
#include <vector>

class Solution {
public:
    bool canConstruct(std::string s, int k) {
        if (k > (int)s.size()) return false;
        std::vector<int> counts(26, 0);
        for (char ch : s) counts[ch - 'a']++;
        int oddCount = 0;
        for (int c : counts) if (c % 2 == 1) oddCount++;
        return oddCount <= k;
    }
};

class Solution {
    public boolean canConstruct(String s, int k) {
        if (k > s.length()) return false;
        int[] counts = new int[26];
        for (char ch : s.toCharArray()) counts[ch - 'a']++;
        int oddCount = 0;
        for (int c : counts) if (c % 2 == 1) oddCount++;
        return oddCount <= k;
    }
}

var canConstruct = function(s, k) {
    if (k > s.length) return false;
    const counts = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) counts[s.charCodeAt(i) - 97]++;
    let oddCount = 0;
    for (const c of counts) if (c % 2 === 1) oddCount++;
    return oddCount <= k;
};
